import { useQuery, type UseQueryOptions } from "@tanstack/react-query";
import { getCharacterHandler } from "../handlers/getCharacterHandler";
import type { ApiError } from "../runtime/client";

type Data = Awaited<ReturnType<typeof getCharacterHandler>>;

export function useGetCharacter(
  options?: Omit<UseQueryOptions<Data, ApiError>, "queryKey" | "queryFn">,
) {
  return useQuery<Data, ApiError>({
    queryKey: ["getCharacter"],
    queryFn: () => getCharacterHandler(),
    ...options,
  });
}
